'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useCourses } from '../../../lib/hooks/use-course';
import {
  useMyPortfolio,
  useUpdatePortfolio,
  useUpdatePortfolioCourses,
} from '../../../lib/hooks/use-portfolio';
import { useUser } from '../../../lib/hooks/use-auth';

export default function PortfolioSettingsPage() {
  const router = useRouter();
  const { user } = useUser();
  const { data: courses } = useCourses();
  const { data: portfolio, isLoading } = useMyPortfolio();
  const updatePortfolio = useUpdatePortfolio();
  const updateCourses = useUpdatePortfolioCourses();

  const [title, setTitle] = useState('');
  const [bio, setBio] = useState('');
  const [isPublic, setIsPublic] = useState(true);
  const [selectedCourseIds, setSelectedCourseIds] = useState<number[]>([]);
  const [saveSuccess, setSaveSuccess] = useState(false);

  useEffect(() => {
    if (portfolio) {
      setTitle(portfolio.title || '');
      setBio(portfolio.bio || '');
      setIsPublic(portfolio.isPublic ?? true);
      setSelectedCourseIds(
        portfolio.courses?.map((c: any) => c.course.id) || [],
      );
    }
  }, [portfolio]);

  const handleSave = async () => {
    await updatePortfolio.mutateAsync({ title, bio, isPublic });
    await updateCourses.mutateAsync(selectedCourseIds);
    setSaveSuccess(true);
    setTimeout(() => setSaveSuccess(false), 3000);
  };

  const toggleCourse = (courseId: number) => {
    setSelectedCourseIds((prev) =>
      prev.includes(courseId)
        ? prev.filter((id) => id !== courseId)
        : [...prev, courseId],
    );
  };

  const portfolioUrl = user?.username ? `/p/${user.username}` : null;
  const isSaving = updatePortfolio.isPending || updateCourses.isPending;

  return (
    <div className="p-6">
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center justify-between mb-8">
          <h1 className="text-2xl font-bold">Portfolio Settings</h1>
          <div className="flex items-center gap-3">
            {portfolioUrl && (
              <a
                href={portfolioUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-[#9F80DA] hover:underline"
              >
                View Portfolio
              </a>
            )}
            <button
              onClick={handleSave}
              disabled={isSaving}
              className="px-4 py-2 bg-gradient-to-r from-[#9F80DA] to-[#8A6BC5] text-white rounded-lg text-sm font-medium hover:from-[#8A6BC5] hover:to-[#7B5BB5] transition-all disabled:opacity-50"
            >
              {isSaving ? 'Saving...' : 'Save changes'}
            </button>
          </div>
        </div>

        {saveSuccess && (
          <div className="mb-6 p-3 bg-green-50 border border-green-200 text-green-700 rounded-lg text-sm">
            Portfolio saved successfully!
          </div>
        )}

        {!user?.username && (
          <div className="mb-6 p-4 bg-amber-50 border border-amber-200 text-amber-800 rounded-lg text-sm">
            You need a username to have a public portfolio URL.{' '}
            <button
              onClick={() => router.push('/dashboard/account')}
              className="underline font-medium"
            >
              Set your username →
            </button>
          </div>
        )}

        {portfolioUrl && (
          <div className="mb-6 p-4 bg-gray-50 border border-gray-200 rounded-lg text-sm flex items-center gap-2">
            <span className="text-gray-500">Your portfolio URL:</span>
            <a
              href={portfolioUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="text-[#9F80DA] font-medium hover:underline"
            >
              acadion.ai{portfolioUrl}
            </a>
          </div>
        )}

        {isLoading ? (
          <div className="py-20 text-center text-gray-400">Loading...</div>
        ) : (
          <div className="space-y-6">
            {/* Visibility toggle */}
            <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl border border-gray-200">
              <div>
                <h3 className="font-medium text-[#1a1a1a]">Public portfolio</h3>
                <p className="text-sm text-gray-500 mt-0.5">
                  Anyone with the link can view your portfolio
                </p>
              </div>
              <button
                onClick={() => setIsPublic(!isPublic)}
                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                  isPublic ? 'bg-[#9F80DA]' : 'bg-gray-300'
                }`}
              >
                <span
                  className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                    isPublic ? 'translate-x-6' : 'translate-x-1'
                  }`}
                />
              </button>
            </div>

            {/* Title */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Portfolio title
              </label>
              <input
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="My portfolio"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm outline-none focus:border-[#9F80DA] transition-colors"
              />
            </div>

            {/* Bio */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Bio
              </label>
              <textarea
                value={bio}
                onChange={(e) => setBio(e.target.value)}
                placeholder="Tell visitors about yourself and your work..."
                rows={4}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm outline-none focus:border-[#9F80DA] transition-colors resize-none"
              />
            </div>

            {/* Course selection */}
            <div>
              <h3 className="font-medium text-[#1a1a1a] mb-1">
                Visible courses
              </h3>
              <p className="text-sm text-gray-500 mb-4">
                Choose which completed courses appear in your portfolio
              </p>

              {!courses || courses.filter((c) => c.status === 'completed').length === 0 ? (
                <p className="text-sm text-gray-400 italic p-4 bg-gray-50 rounded-xl">
                  You don&apos;t have any completed courses yet. Generate a course
                  first.
                </p>
              ) : (
                <div className="space-y-2">
                  {courses
                    .filter((c) => c.status === 'completed')
                    .map((course) => (
                      <label
                        key={course.id}
                        className="flex items-center gap-3 p-3 border border-gray-200 rounded-xl cursor-pointer hover:border-[#9F80DA] transition-colors"
                      >
                        <input
                          type="checkbox"
                          checked={selectedCourseIds.includes(course.id)}
                          onChange={() => toggleCourse(course.id)}
                          className="accent-[#9F80DA] w-4 h-4"
                        />
                        <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-[#9F80DA]/20 to-[#8A6BC5]/20 flex items-center justify-center flex-shrink-0">
                          <svg
                            className="w-4 h-4 text-[#9F80DA]/60"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={1.5}
                              d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"
                            />
                          </svg>
                        </div>
                        <span className="text-sm font-medium text-[#1a1a1a]">
                          {course.title || 'Untitled Course'}
                        </span>
                      </label>
                    ))}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
